// Skip records a file that adoption selection passed over, and why.
type Skip struct {
	Path   string
	Reason Reason
	Detail string
}

// Candidate is a file that can be adopted, with its resolved template and record.
type Candidate struct {
	Path     string
	Package  *genpkg.Package
	Template string
	Captures map[string]string
	Record   *record.Record
	Src      []byte
}

// SelectConfig holds the inputs to Select.
type SelectConfig struct {
	Root    string
	Set     *genpkg.Set
	Records *record.Set
	Tests   bool
}

// Select walks each of paths under cfg.Root and returns the files that can be
// adopted, in walk order, together with a Skip for every file that cannot be.
func Select(cfg SelectConfig, paths []string) ([]Candidate, []Skip, error) {
	var cands []Candidate
	var skips []Skip
	seen := map[string]bool{}
	var visit func(rel string) error
	visit = func(rel string) error {
		abs := filepath.Join(cfg.Root, filepath.FromSlash(rel))
		info, err := os.Stat(abs)
		if err != nil {
			return fmt.Errorf("stat %s: %w", rel, err)
		}
		if info.IsDir() {
			entries, err := os.ReadDir(abs)
			if err != nil {
				return fmt.Errorf("read dir %s: %w", rel, err)
			}
			for _, e := range entries {
				name := e.Name()
				if e.IsDir() && strings.HasPrefix(name, ".") {
					continue
				}
				if err := visit(path.Join(rel, name)); err != nil {
					return err
				}
			}
			return nil
		}
		if !info.Mode().IsRegular() || seen[rel] {
			return nil
		}
		seen[rel] = true
		skip := func(r Reason, detail string) {
			skips = append(skips, Skip{Path: rel, Reason: r, Detail: detail})
		}
		pkgs := cfg.Set.ForExtension(filepath.Ext(rel))
		if len(pkgs) == 0 {
			skip(ReasonNoPackage, "")
			return nil
		}
		if pkg, entry, ok := cfg.Set.Unmanaged(rel); ok {
			skip(ReasonUnmanaged, pkg+": "+entry)
			return nil
		}
		src, err := os.ReadFile(abs)
		if err != nil {
			return fmt.Errorf("read %s: %w", rel, err)
		}
		pkg := pkgs[0]
		if !cfg.Tests {
			if _, ok := pathpat.MatchAny(pkg.TestPaths, rel); ok {
				skip(ReasonTest, "")
				return nil
			}
		}
		lines := strings.Split(string(src), "\n")
		if len(lines) > 20 {
			lines = lines[:20]
		}
		for _, line := range lines {
			if strings.Contains(line, "DO NOT EDIT") || strings.Contains(line, "@generated") {
				skip(ReasonGenerated, "")
				return nil
			}
		}
		if strings.Contains(string(src), pkg.Comment().Prefix+" sedum:") {
			skip(ReasonAlreadyAdopted, "")
			return nil
		}
		var imprints []*record.Record
		for _, r := range cfg.Records.Records {
			if r.Deprecated || r.Type != "imprint" || !r.Authorizes(rel) {
				continue
			}
			if _, forbidden := r.Forbids(rel); forbidden {
				continue
			}
			imprints = append(imprints, r)
		}
		if len(imprints) == 0 {
			skip(ReasonNoImprint, "")
			return nil
		}
		if len(imprints) > 1 {
			ids := make([]string, 0, len(imprints))
			for _, r := range imprints {
				ids = append(ids, r.ID)
			}
			skip(ReasonAmbiguousImprint, strings.Join(ids, ", "))
			return nil
		}
		imprint := imprints[0]
		res, _, err := resolve.Paths(cfg.Set, &record.Set{Records: []*record.Record{{ID: imprint.ID, Paths: []string{rel}}}}, nil)
		if err != nil {
			skip(ReasonUnresolved, err.Error())
			return nil
		}
		if len(res) == 0 {
			skip(ReasonUnresolved, "no resolution")
			return nil
		}
		r := res[0]
		if r.Unmanaged {
			skip(ReasonUnmanaged, "")
			return nil
		}
		if r.Template == "" {
			skip(ReasonNoTemplate, "")
			return nil
		}
		cands = append(cands, Candidate{Path: rel, Package: r.Package, Template: r.Template, Captures: r.Captures, Record: imprint, Src: src})
		return nil
	}
	for _, p := range paths {
		clean := path.Clean(filepath.ToSlash(p))
		if clean == ".." || strings.HasPrefix(clean, "../") || path.IsAbs(clean) {
			return nil, nil, fmt.Errorf("path %q escapes root", p)
		}
		if err := visit(clean); err != nil {
			return nil, skips, err
		}
	}
	return cands, skips, nil
}

// newSelectFixture writes a small generators tree and returns a root directory,
// a loaded generator set, and an imprint record set.
func newSelectFixture(t *testing.T) (string, *genpkg.Set, *record.Set) {
	t.Helper()
	gen := t.TempDir()
	write := func(rel, body string) {
		t.Helper()
		p := filepath.Join(gen, filepath.FromSlash(rel))
		if err := os.MkdirAll(filepath.Dir(p), 0o755); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(p, []byte(body), 0o644); err != nil {
			t.Fatal(err)
		}
	}
	write("py/sedum.yaml", `name: py
extensions: [".py"]
comment_prefix: "#"
test_paths: ["test_*.py"]
unmanaged: ["setup.py"]
`)
	write("py/files/{name}.py", "# sedum:anchor:decls\n")
	write("py/files/*/{name}.py", "# sedum:anchor:decls\n")
	write("py/actions/actions.yaml", `actions:
  setThing:
    kwargs:
      file: { type: string, required: true }
      name: { type: string, required: true }
      code: { type: string, required: true }
    injects_into: "{{file}}"
    anchor: decls
`)
	write("py/actions/setThing.py", "{{code}}\n")
	set, findings, err := genpkg.Load(gen, genpkg.Options{})
	if err != nil {
		t.Fatal(err)
	}
	if len(findings) > 0 {
		t.Fatalf("generator findings: %v", findings)
	}
	root := t.TempDir()
	records := &record.Set{Records: []*record.Record{{ID: "imp-1", Type: "imprint", Patterns: []string{"*.py"}}}}
	return root, set, records
}

func TestSelectCandidate(t *testing.T) {
	root, set, records := newSelectFixture(t)
	src := []byte(`x = 1
`)
	if err := os.WriteFile(filepath.Join(root, "a.py"), src, 0o644); err != nil {
		t.Fatal(err)
	}
	cands, skips, err := Select(SelectConfig{Root: root, Set: set, Records: records}, []string{"a.py"})
	if err != nil {
		t.Fatal(err)
	}
	if len(skips) != 0 {
		t.Fatalf("skips = %+v, want none", skips)
	}
	if len(cands) != 1 {
		t.Fatalf("got %d candidates, want 1", len(cands))
	}
	c := cands[0]
	if c.Template != "{name}.py" {
		t.Errorf("Template = %q, want %q", c.Template, "{name}.py")
	}
	if c.Record == nil || c.Record.ID != "imp-1" {
		t.Errorf("Record = %+v, want ID imp-1", c.Record)
	}
	if c.Captures["name"] != "a" {
		t.Errorf("Captures[name] = %q, want %q", c.Captures["name"], "a")
	}
	if !bytes.Equal(c.Src, src) {
		t.Errorf("Src = %q, want %q", c.Src, src)
	}
}

func TestSelectSkipReasons(t *testing.T) {
	cases := []struct {
		name string
		file string
		body string
		want Reason
	}{
		{"unmanaged", "setup.py", "x = 1\n", ReasonUnmanaged},
		{"test", "test_a.py", "x = 1\n", ReasonTest},
		{"generated", "gen.py", "# DO NOT EDIT\nx = 1\n", ReasonGenerated},
		{"already adopted", "done.py", "# sedum:setThing {}\n", ReasonAlreadyAdopted},
		{"no package", "notes.txt", "hello\n", ReasonNoPackage},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			root, set, records := newSelectFixture(t)
			if err := os.WriteFile(filepath.Join(root, tc.file), []byte(tc.body), 0o644); err != nil {
				t.Fatal(err)
			}
			cands, skips, err := Select(SelectConfig{Root: root, Set: set, Records: records}, []string{tc.file})
			if err != nil {
				t.Fatal(err)
			}
			if len(cands) != 0 || len(skips) != 1 {
				t.Fatalf("got %d candidates and %d skips, want 0 and 1", len(cands), len(skips))
			}
			if skips[0].Reason != tc.want {
				t.Errorf("Reason = %q, want %q", skips[0].Reason, tc.want)
			}
		})
	}
}

